package cn.nebulaedata.cccs.nebuwork.backend.api.knowledge;

import cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiException;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.springframework.stereotype.Component;
import java.util.*;
import static cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiSupport.map;
import static cn.nebulaedata.cccs.nebuwork.backend.api.knowledge.KnowledgeValues.*;
import static cn.nebulaedata.cccs.nebuwork.backend.api.knowledge.KnowledgeRestClient.segment;

/** V101 projections retain the upstream's immutable source/file/parse identities. */
@Component
public class NebulaeV101RestDriver implements KnowledgeDriver {
    public static final String ID="nebulae-v101-rest";
    final KnowledgeRestClient client; final ObjectMapper json;
    public NebulaeV101RestDriver(KnowledgeRestClient client,ObjectMapper json){this.client=client;this.json=json;}
    public String id(){return ID;}
    public Map<String,Object> descriptor(){return map("id",ID,"name","Nebulae V101","transport","rest","knowledgeBaseTypes",Collections.singletonList("document"),"capabilities",Arrays.asList("collections","documents","document","search","manage","create","wiki","upload","capabilities","chunk","graph","gallery","preview","v101-workspace","tasks","sources","resumable-upload","qa","extraction"));}
    static JsonNode data(JsonNode n){return n.has("data")?n.path("data"):n;}
    static String kb(String id){return "/knowledge-bases/"+segment(id);}
    static String doc(String id){return "/knowledge/"+segment(id);}
    static String versions(JsonNode in){StringJoiner q=new StringJoiner("&");for(String[] p:new String[][]{{"fileVersionId","file_version_id"},{"parseVersionId","parse_version_id"}})if(!in.path(p[0]).asText().isEmpty())q.add(p[1]+"="+segment(in.path(p[0]).asText()));return q.length()==0?"":"?"+q;}
    static String page(JsonNode n){return "page="+NebulaeV100RestDriver.integer(n,"page",1,1000000)+"&page_size="+NebulaeV100RestDriver.integer(n,"pageSize",20,100);}
    JsonNode request(KnowledgeRestClient.Session s,String path){return data(s.request("GET",path,null));}
    JsonNode library(KnowledgeRestClient.Session s,String id){JsonNode n=request(s,kb(id));if(!id.equals(n.path("id").asText()))throw new ApiException(502,"V101 返回了不匹配的知识库");return n;}
    JsonNode document(KnowledgeRestClient.Session s,String collection,String id){JsonNode n=request(s,doc(id));if(!collection.equals(n.path("knowledge_base_id").asText())||!id.equals(n.path("id").asText()))throw new ApiException(404,"文档不属于当前知识库");return n;}
    public JsonNode execute(String endpoint,Map<String,String> headers,String operation,String collection,JsonNode in){java.util.function.Function<KnowledgeRestClient.Session,JsonNode> call=s->{JsonNode n=read(s,operation,collection,in);NebulaeV100RestDriver.scrub(n);return n;};return "search".equals(operation)?client.executeRetrieval(endpoint,headers,call):client.execute(endpoint,headers,call);}
    private ObjectNode libraryDTO(JsonNode n){return json.valueToTree(map("id",n.path("id").asText(),"name",n.path("name").asText(),"description",n.path("description").asText(),"type","document","documentCount",n.get("document_count"),"indexingStatus","unknown"));}
    ObjectNode documentDTO(JsonNode n){ObjectNode d=json.valueToTree(map("id",n.path("id").asText(),"collectionId",n.path("knowledge_base_id").asText(),"title",n.path("name").asText(),"fileName",n.path("name").asText(),"fileType",n.path("file_type").asText(),"contentKind","document","parseStatus",n.path("status").asText(),"folderPath",n.path("relative_path").asText(),"fileVersionId",n.path("current_file_version_id").asText(""),"parseVersionId",n.path("current_parse_version_id").asText("")));for(String[] p:new String[][]{{"size","fileSize"},{"hash","sourceHash"},{"created_at","createdAt"},{"updated_at","updatedAt"}})if(n.hasNonNull(p[0]))d.set(p[1],n.get(p[0]));return d;}
    ObjectNode citation(JsonNode source,String collection){if(!collection.equals(source.path("knowledge_base_id").asText()))throw new ApiException(502,"V101 返回了跨库来源");return json.valueToTree(map("collectionId",collection,"documentId",source.path("knowledge_id").asText(),"title",source.path("file_name").asText(),"contentKind","document","sourceRefId",source.path("source_ref_id").asText(),"fileVersionId",source.path("file_version_id").asText(),"parseVersionId",source.path("parse_version_id").asText(),"sourceHash",source.path("file_hash").asText(),"sourceLocators",locators(source),"precision",source.path("precision"),"mappingMethod",source.path("mapping_method"),"partial",source.path("partial").asBoolean()));}
    ArrayNode locators(JsonNode source){ArrayNode out=json.createArrayNode();for(JsonNode raw:source.path("locators")){ObjectNode n=raw.deepCopy();String type=n.path("type").asText();if("page".equals(type)||"image".equals(type)&&n.has("page"))n.put("type","pdf");if("paragraph".equals(type)){n.put("type","docx");try{n.put("block",Integer.parseInt(n.path("paragraph_id").asText()));}catch(NumberFormatException ignored){}}if("table".equals(type)){n.put("type","docx");try{n.put("block",Integer.parseInt(n.path("after_paragraph_id").asText()));}catch(NumberFormatException ignored){}}n.put("source_hash",source.path("file_hash").asText());n.put("quote",source.path("quote").asText());n.put("partial",source.path("partial").asBoolean());out.add(n);}return out;}
    JsonNode source(KnowledgeRestClient.Session s,String collection,String id){JsonNode n=request(s,"/sources/"+segment(id));if(!collection.equals(n.path("knowledge_base_id").asText()))throw new ApiException(404,"来源不属于当前知识库");return n;}
    private ObjectNode paged(String key,ArrayNode rows,JsonNode raw,JsonNode in){return json.valueToTree(map(key,rows,"total",raw.path("meta").path("total").asLong(rows.size()),"page",NebulaeV100RestDriver.integer(in,"page",1,1000000),"pageSize",NebulaeV100RestDriver.integer(in,"pageSize",20,100),"hasMore",raw.path("meta").path("has_more").asBoolean()));}
    private JsonNode read(KnowledgeRestClient.Session s,String op,String collection,JsonNode in){
        if("collections".equals(op)){ArrayNode rows=json.createArrayNode();for(int p=1;p<=100;p++){JsonNode raw=s.request("GET","/knowledge-bases?page_size=100&page="+p,null);for(JsonNode n:data(raw))rows.add(libraryDTO(n));if(!raw.path("meta").path("has_more").asBoolean())return json.valueToTree(map("collections",rows,"tools",Collections.emptyList()));}throw new ApiException(502,"V101 目录超过分页限制");}
        JsonNode lib=library(s,collection);
        if("library".equals(op))return libraryDTO(lib);
        if("capabilities".equals(op)){JsonNode actual=request(s,kb(collection)+"/capabilities");ObjectNode caps=json.createObjectNode();for(String[] pair:new String[][]{{"document","keyword"},{"search","multi"},{"wiki","wiki"},{"graph","graph"},{"gallery","image_text"},{"preview","keyword"}}){JsonNode c=actual.path(pair[1]);caps.set(pair[0],json.valueToTree(map("supported",true,"enabled",true,"available",c.path("ready").asBoolean(),"configured",c.path("configured").asBoolean(),"reason",c.path("reason"))));}return json.valueToTree(map("type","document","capabilities",caps,"searchModes",actual));}
        if("faq".equals(in.path("contentKind").asText()))throw new ApiException(422,"V101 不提供 FAQ 功能");
        if("wiki.folders".equals(op)){JsonNode all=request(s,kb(collection)+"/wiki/folders");ArrayNode rows=json.createArrayNode();String parent=in.path("parent_id").asText();for(JsonNode n:all)if(parent.equals(n.path("parent_id").asText()))rows.add(n);return json.valueToTree(map("folders",rows));}
        if("wiki.stats".equals(op))return request(s,kb(collection)+"/wiki/stats");
        if("wiki.graph".equals(op)){JsonNode g=request(s,kb(collection)+"/wiki/graph?view=overview");ArrayNode nodes=json.createArrayNode(),edges=json.createArrayNode();for(JsonNode n:g.path("nodes")){ObjectNode copy=n.deepCopy();copy.put("slug",n.path("id").asText());nodes.add(copy);}for(JsonNode e:g.path("edges"))edges.add(json.valueToTree(map("source",e.path("source_id"),"target",e.path("target_id"),"kind",e.path("kind"))));return json.valueToTree(map("nodes",nodes,"edges",edges,"unresolvedReferences",g.path("unresolved_references")));}
        if("documents".equals(op)&&"wiki".equals(in.path("contentKind").asText()))return wikiPages(s,collection,in);
        if("source".equals(op)){JsonNode src=source(s,collection,text(in,"sourceRefId",512,true));return json.valueToTree(map("citation",citation(src,collection),"text",src.path("quote")));}
        if("document".equals(op)&&"wiki".equals(in.path("contentKind").asText()))return wikiDocument(s,collection,in);
        if("documents".equals(op)){String q=in.path("query").asText();JsonNode raw=s.request("GET",kb(collection)+"/knowledge?"+page(in)+(q.isEmpty()?"":"&q="+segment(q)),null);ArrayNode rows=json.createArrayNode();for(JsonNode n:data(raw))rows.add(documentDTO(n));return paged("documents",rows,raw,in);}
        if("chunk".equals(op)||"document".equals(op)&&in.hasNonNull("chunkId"))return chunk(s,collection,in);
        if("document".equals(op)){String id=text(in,"documentId",512,true);ObjectNode d=documentDTO(document(s,collection,id));String query=versions(in);if(query.isEmpty()&&d.path("parseVersionId").asText().isEmpty())return json.valueToTree(map("document",d,"chunks",Collections.emptyList(),"hasMore",false));JsonNode content=request(s,doc(id)+"/content"+query);d.set("extractedText",content.path("display_content").isTextual()?content.path("display_content"):content.path("content"));d.set("fileVersionId",content.path("file_version_id"));d.set("parseVersionId",content.path("parse_version_id"));for(JsonNode v:request(s,doc(id)+"/versions"))if(v.path("id").equals(content.path("file_version_id")))d.set("sourceHash",v.path("hash"));JsonNode raw=s.request("GET",doc(id)+"/chunks"+(query.isEmpty()?"?":query+"&")+page(in),null);ArrayNode chunks=json.createArrayNode();for(JsonNode c:data(raw)){ObjectNode copy=c.deepCopy();copy.set("source_locators",c.path("locators"));chunks.add(copy);}ObjectNode out=paged("chunks",chunks,raw,in);out.set("document",d);return out;}
        if("graph".equals(op))return graph(s,collection,in);
        if("gallery".equals(op))return gallery(s,collection,in);
        if("search".equals(op)){String q=text(in,"query",4096,true);ObjectNode body=json.createObjectNode();body.put("query_text",q);body.put("mode","wiki".equals(in.path("contentKind").asText())?"wiki":in.path("mode").asText("hybrid"));body.set("knowledge_base_ids",json.valueToTree(Collections.singletonList(collection)));body.put("top_k",NebulaeV100RestDriver.integer(in,"topK",10,100));body.put("include_sources",true);body.put("include_context",true);body.put("allow_partial",true);JsonNode raw=data(s.request("POST","/search",body));ArrayNode hits=json.createArrayNode();for(JsonNode hit:raw.path("results")){if(!collection.equals(hit.path("knowledge_base_id").asText()))throw new ApiException(502,"V101 检索返回跨库结果");if("wiki_page".equals(hit.path("result_type").asText())){for(JsonNode src:hit.path("source_refs"))citation(src,collection);hits.add(json.valueToTree(map("text",hit.path("content"),"citation",map("collectionId",collection,"documentId",hit.path("result_id").asText(),"title",hit.path("title"),"contentKind","wiki"),"scores",hit.path("scores"),"sourceKind","wiki")));continue;}for(JsonNode src:hit.path("source_refs")){ObjectNode cite=citation(src,collection);cite.set("chunkId",hit.path("chunk_id"));hits.add(json.valueToTree(map("text",hit.path("content"),"citation",cite,"scores",hit.path("scores"),"sourceKind",hit.path("result_type"))));}}return json.valueToTree(map("query",q,"results",hits,"partial",raw.path("meta").path("warnings").size()>0,"warnings",raw.path("meta").path("warnings"),"meta",raw.path("meta")));}
        throw new ApiException(422,"V101 不支持此操作");
    }
    private JsonNode wikiPages(KnowledgeRestClient.Session s,String collection,JsonNode in){ArrayNode all=json.createArrayNode();String folder=in.path("folder_id").asText(),q=in.path("query").asText().toLowerCase(Locale.ROOT);for(int p=1;p<=100;p++){JsonNode rows=request(s,kb(collection)+"/wiki/pages?page_size=100&page="+p);for(JsonNode n:rows)if((folder.isEmpty()||folder.equals(n.path("folder_id").asText()))&&(q.isEmpty()||(n.path("title").asText()+n.path("content").asText()).toLowerCase(Locale.ROOT).contains(q)))all.add(json.valueToTree(map("id",n.path("id"),"title",n.path("title"),"contentKind","wiki","folderId",n.path("folder_id"),"updatedAt",n.path("updated_at"))));if(rows.size()<100)break;if(p==100)throw new ApiException(502,"Wiki 列表超过读取预算");}int page=NebulaeV100RestDriver.integer(in,"page",1,1000000),size=NebulaeV100RestDriver.integer(in,"pageSize",20,100);ArrayNode rows=json.createArrayNode();for(int i=(page-1)*size;i<Math.min(page*size,all.size());i++)rows.add(all.get(i));return json.valueToTree(map("documents",rows,"total",all.size(),"page",page,"pageSize",size,"hasMore",page*size<all.size()));}
    private JsonNode chunk(KnowledgeRestClient.Session s,String collection,JsonNode in){String id=in.path("sourceRefId").asText();if(id.isEmpty()){String document=text(in,"documentId",512,true),chunk=text(in,"chunkId",512,true);document(s,collection,document);for(int p=1;p<=100&&id.isEmpty();p++){JsonNode raw=s.request("GET",doc(document)+"/chunks"+(versions(in).isEmpty()?"?":versions(in)+"&")+"page_size=100&page="+p,null);for(JsonNode n:data(raw))if(chunk.equals(n.path("id").asText()))id=n.path("source_ref_id").asText();if(!raw.path("meta").path("has_more").asBoolean())break;}if(id.isEmpty())throw new ApiException(404,"分块不存在于指定版本");}JsonNode src=source(s,collection,id);if(in.hasNonNull("documentId")&&!in.path("documentId").asText().equals(src.path("knowledge_id").asText()))throw new ApiException(404,"来源不属于当前文档");for(String[] p:new String[][]{{"fileVersionId","file_version_id"},{"parseVersionId","parse_version_id"}})if(!in.path(p[0]).asText().isEmpty()&&!in.path(p[0]).asText().equals(src.path(p[1]).asText()))throw new ApiException(409,"来源版本不匹配");ObjectNode d=documentDTO(document(s,collection,src.path("knowledge_id").asText()));d.set("sourceHash",src.path("file_hash"));d.set("fileVersionId",src.path("file_version_id"));d.set("parseVersionId",src.path("parse_version_id"));String content=src.path("metadata").path("generated_text").asText(src.path("quote").asText());return json.valueToTree(map("document",d,"citation",citation(src,collection),"chunk",map("id",in.path("chunkId"),"content",content,"source_locators",locators(src)),"chunks",Collections.singletonList(map("content",content,"source_locators",locators(src)))));}
    private JsonNode graph(KnowledgeRestClient.Session s,String collection,JsonNode in){String q=in.path("nodeId").asText(in.path("query").asText());JsonNode raw=data(s.request("POST",kb(collection)+"/graph/query",json.valueToTree(map("query",q,"limit",Math.min(100,NebulaeV100RestDriver.integer(in,"limit",50,200)),"max_hops",1))));ArrayNode nodes=json.createArrayNode(),edges=json.createArrayNode(),sources=json.createArrayNode();Set<String> ids=new LinkedHashSet<>();for(JsonNode n:raw.path("nodes")){nodes.add(json.valueToTree(map("id",n.path("name"),"name",n.path("name"),"title",n.path("name"),"type",n.path("type"),"description",n.path("description"))));for(JsonNode id:n.path("source_ids"))ids.add(id.asText());}for(JsonNode r:raw.path("relations")){edges.add(json.valueToTree(map("id",r.path("id"),"source",r.path("source"),"target",r.path("target"),"label",r.path("relation"),"relation",r.path("relation"))));if(r.hasNonNull("source_ref_id"))ids.add(r.path("source_ref_id").asText());}int count=0;for(String id:ids){if(count++>=100)break;JsonNode src=source(s,collection,id);sources.add(json.valueToTree(map("text",src.path("quote"),"citation",citation(src,collection),"sourceKind","graph")));}return json.valueToTree(map("nodes",nodes,"edges",edges,"sources",sources,"truncated",raw.path("truncated")));}

    private JsonNode wikiDocument(KnowledgeRestClient.Session s,String collection,JsonNode in){
        String id=text(in,"documentId",512,true);JsonNode graph=request(s,kb(collection)+"/wiki/graph?view=overview");Map<String,String> byTitle=new LinkedHashMap<>(),titles=new LinkedHashMap<>();for(JsonNode n:graph.path("nodes")){byTitle.put(n.path("title").asText(),n.path("id").asText());titles.put(n.path("id").asText(),n.path("title").asText());}if(byTitle.containsKey(id))id=byTitle.get(id);
        JsonNode p=request(s,kb(collection)+"/wiki/pages/"+segment(id));String content=p.path("content").asText();java.util.regex.Matcher matcher=java.util.regex.Pattern.compile("\\[\\[([^\\]\\n]+)\\]\\]").matcher(content);StringBuffer linked=new StringBuffer();while(matcher.find()){String title=matcher.group(1);matcher.appendReplacement(linked,java.util.regex.Matcher.quoteReplacement(byTitle.containsKey(title)?"[["+byTitle.get(title)+"|"+title+"]]":matcher.group()));}matcher.appendTail(linked);
        ObjectNode d=json.valueToTree(map("id",p.path("id"),"collectionId",collection,"title",p.path("title"),"contentKind","wiki","extractedText",linked.toString(),"folderId",p.path("folder_id"),"updatedAt",p.path("updated_at")));ArrayNode refs=d.putArray("sourceRefs"),sources=d.putArray("sources"),incoming=d.putArray("inLinks"),outgoing=d.putArray("outLinks");for(JsonNode edge:graph.path("edges")){String from=edge.path("source_id").asText(),to=edge.path("target_id").asText();if(id.equals(from))outgoing.add(to+"|"+titles.getOrDefault(to,to));if(id.equals(to))incoming.add(from+"|"+titles.getOrDefault(from,from));}Set<String> seen=new HashSet<>();for(JsonNode ref:p.path("source_ids")){JsonNode src=source(s,collection,ref.asText());String document=src.path("knowledge_id").asText();if(seen.add(document)){refs.add(document+"|"+src.path("file_name").asText());ObjectNode original=citation(src,collection);original.put("available",true);sources.add(original);}}return json.valueToTree(map("document",d));
    }
    private JsonNode gallery(KnowledgeRestClient.Session s,String collection,JsonNode in){
        if(in.path("attrFilters").size()>0||in.path("attrRules").size()>0||!in.path("sortBy").asText().isEmpty())throw new ApiException(422,"V101 没有动态图片属性筛选与排序能力");
        if("config".equals(in.path("mode").asText()))return json.valueToTree(map("config",map("attributes",Collections.emptyList(),"sorting",false)));
        List<String> documents=new ArrayList<>();for(JsonNode id:in.path("documentIds")){document(s,collection,id.asText());documents.add(id.asText());}if(documents.size()>100)throw new ApiException(422,"单次最多筛选 100 篇文档");
        ArrayNode candidates=json.createArrayNode();String query=in.path("query").asText();boolean truncated=false;
        if(!query.isEmpty()){ObjectNode body=json.valueToTree(map("knowledge_base_ids",Collections.singletonList(collection),"query_text",query,"mode","image_text","top_k",100,"candidate_k",500,"include_sources",true,"rerank",map("mode","disabled")));if(!documents.isEmpty())body.set("knowledge_ids",json.valueToTree(documents));JsonNode result=data(s.request("POST","/search",body));Set<String> seen=new HashSet<>();for(JsonNode hit:result.path("results"))for(JsonNode src:hit.path("source_refs")){String asset=src.path("asset_id").asText("");if(!asset.isEmpty()&&seen.add(asset))candidates.add(request(s,"/images/"+segment(asset)));}truncated=result.path("meta").path("truncated").asBoolean();}
        else {List<String> paths=new ArrayList<>();if(documents.isEmpty())paths.add(kb(collection)+"/images");else for(String id:documents)paths.add(doc(id)+"/images");for(String path:paths)for(int page=1;page<=100;page++){JsonNode raw=s.request("GET",path+"?page_size=100&page="+page,null);for(JsonNode n:data(raw))candidates.add(n);if(!raw.path("meta").path("has_more").asBoolean())break;if(page==100)throw new ApiException(502,"图片列表超过读取预算，请限定来源文档");}}
        int page=NebulaeV100RestDriver.integer(in,"page",1,1000000),size=NebulaeV100RestDriver.integer(in,"pageSize",20,100);ArrayNode rows=json.createArrayNode();for(int i=(page-1)*size;i<Math.min(page*size,candidates.size());i++){JsonNode n=candidates.get(i);document(s,collection,n.path("knowledge_id").asText());JsonNode detail=n.has("source_refs")?n:request(s,"/images/"+segment(n.path("id").asText()));JsonNode src=source(s,collection,n.path("source_ref_id").asText());String caption="";for(JsonNode ref:detail.path("source_refs"))if(ref.path("generated_text").isTextual())caption=ref.path("generated_text").asText();rows.add(json.valueToTree(map("id",n.path("id"),"documentId",n.path("knowledge_id"),"title",n.path("name"),"caption",caption,"ocrText",detail.path("display_recognized_text").asText(detail.path("recognized_text").asText()),"citation",citation(src,collection),"sourceKind","image","enabled",true)));}return json.valueToTree(map("items",rows,"page",page,"total",candidates.size(),"hasMore",page*size<candidates.size(),"truncated",truncated,"config",map("attributes",Collections.emptyList(),"sorting",false)));
    }
}
